import{_ as o,o as t,c as a,a5 as n}from"./chunks/framework.Cooo9kuv.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"790批量将每个文件夹下图片分别合并为一个word文档","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["WORD批处理","图片批处理"],"标签":["图片合并为word"]},"headers":[],"relativePath":"md/WORD批处理/790批量将每个文件夹下图片分别合并为一个word文档.md","filePath":"md/WORD批处理/790批量将每个文件夹下图片分别合并为一个word文档.md"}'),s={name:"md/WORD批处理/790批量将每个文件夹下图片分别合并为一个word文档.md"};function e(d,r,p,g,_,b){return t(),a("div",null,[...r[0]||(r[0]=[n('<h3 id="批量将每个文件夹下图片分别合并为一个word文档" tabindex="-1">批量将每个文件夹下图片分别合并为一个word文档 <a class="header-anchor" href="#批量将每个文件夹下图片分别合并为一个word文档" aria-label="Permalink to &quot;批量将每个文件夹下图片分别合并为一个word文档&quot;">​</a></h3><p>批量将指定文件夹下各个文件夹下图片按照顺序合并为word文档（docx文档格式），word文档名以各文件夹名命名。</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多图片文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有图片文件。</p><p>【操作方法】：只需要输入A文件夹路径即可，支持子文件夹自动穿透，每个文件夹下图片都会按照顺序合并为一个docx格式的word文档，<strong>word文档名称以文件夹名命名，保存在各文件夹下</strong>。</p><p>【1】、支持的文件格式：所有主流图片格式</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="📑-文件结构树示意" tabindex="-1">📑 文件结构树示意 <a class="header-anchor" href="#📑-文件结构树示意" aria-label="Permalink to &quot;📑 文件结构树示意&quot;">​</a></h3><p>A文件夹根目录下图片合并为word后保存在A文件夹根目录下，word名称为A.docx，B文件夹下图片合并为word后保存在B文件夹下，B1文件夹下图片合并后保存在B1文件夹下............</p><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250720115758175298387878992.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统</p><p>注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1947.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1947.html</a></p>',17)])])}const h=o(s,[["render",e]]);export{i as __pageData,h as default};
